mapper.select:
SELECT a.*
FROM case_info a
JOIN case_info_approve b ON b.case_info_id = a.case_info_id

    a.is_approve = 1 AND a.case_status = 1 and a.is_voided = 1

        AND b.approval_lawyer = #{params.approvalLawyer}


        AND a.case_name LIKE CONCAT('%', #{params.caseName}, '%')


        AND a.case_no LIKE CONCAT('%', #{params.caseNo}, '%')


        AND a.case_type = #{params.caseType}


        AND a.approve_status = #{params.approveStatus}


        AND a.applicant_name = #{params.applicantName}
